// tests/lfm2_f32_kernels.s -- encoder source for the f32 kernel family.
// Generated bytes are transcribed into lib/std/jit_x86_fused.quanta.
// Every one of these is RE-VERIFIED BY EXECUTION in tests/lfm2_f32_enc_verify.c,
// which runs the exact hex byte sequences with known operands.
//
// The verify_* stubs exist only for that harness: verify_pre loads the test
// registers from a context block (rdi) and verify_post stores them back, so a
// single instruction's real register effects can be inspected from C.
.intel_syntax noprefix
.text

// ===================== harness prologue / epilogue ==========================
// ctx: +0 r9_in, +8 r10_in, +16 rax_out, +24 r9_out, +32 r10_out,
//      +64 ymm0, +128 ymm1, +192 ymm2, +256 ymm3, +320 ymm4, +384 ymm5,
//      +448 ymm6, +512 ymm7, +576 ymm8, +640 ymm9,
//      +704 ymm12, +768 ymm13, +832 ymm14, +896 ymm15
.globl verify_pre
verify_pre:
             mov r9, qword ptr [rdi]
             mov r10, qword ptr [rdi+8]
             vmovups ymm0,  ymmword ptr [rdi+64]
             vmovups ymm1,  ymmword ptr [rdi+128]
             vmovups ymm2,  ymmword ptr [rdi+192]
             vmovups ymm3,  ymmword ptr [rdi+256]
             vmovups ymm4,  ymmword ptr [rdi+320]
             vmovups ymm5,  ymmword ptr [rdi+384]
             vmovups ymm6,  ymmword ptr [rdi+448]
             vmovups ymm7,  ymmword ptr [rdi+512]
             vmovups ymm8,  ymmword ptr [rdi+576]
             vmovups ymm9,  ymmword ptr [rdi+640]
             vmovups ymm12, ymmword ptr [rdi+704]
             vmovups ymm13, ymmword ptr [rdi+768]
             vmovups ymm14, ymmword ptr [rdi+832]
             vmovups ymm15, ymmword ptr [rdi+896]
.globl verify_post
verify_post:
             mov qword ptr [rdi+16], rax
             mov qword ptr [rdi+24], r9
             mov qword ptr [rdi+32], r10
             vmovups ymmword ptr [rdi+64],  ymm0
             vmovups ymmword ptr [rdi+128], ymm1
             vmovups ymmword ptr [rdi+192], ymm2
             vmovups ymmword ptr [rdi+256], ymm3
             vmovups ymmword ptr [rdi+320], ymm4
             vmovups ymmword ptr [rdi+384], ymm5
             vmovups ymmword ptr [rdi+448], ymm6
             vmovups ymmword ptr [rdi+512], ymm7
             vmovups ymmword ptr [rdi+576], ymm8
             vmovups ymmword ptr [rdi+640], ymm9
             vmovups ymmword ptr [rdi+704], ymm12
             vmovups ymmword ptr [rdi+768], ymm13
             vmovups ymmword ptr [rdi+832], ymm14
             vmovups ymmword ptr [rdi+896], ymm15
.globl verify_ret
verify_ret:
             ret

// ---- shared reduce (8 f32 lanes -> f64 in xmm0) ----
.globl r_zero
r_zero:      vxorps ymm0, ymm0, ymm0
.globl r_ext
r_ext:       vextractf128 xmm1, ymm0, 1
.globl r_add
r_add:       vaddps xmm0, xmm0, xmm1
.globl r_hadd
r_hadd:      vhaddps xmm0, xmm0, xmm0
.globl r_widen
r_widen:     vcvtss2sd xmm0, xmm0, xmm0
.globl r_movq
r_movq:      vmovq rax, xmm0

// ---- Q4_K f32 group body ----
.globl a_ldq
a_ldq:       vpmovzxbd ymm1, qword ptr [r9]
.globl a_shl28
a_shl28:     vpslld ymm1, ymm1, 28
.globl a_shr28
a_shr28:     vpsrld ymm1, ymm1, 28
.globl a_shr4
a_shr4:      vpsrld ymm1, ymm1, 4
.globl a_cvt
a_cvt:       vcvtdq2ps ymm1, ymm1
.globl a_mul6
a_mul6:      vmulps ymm1, ymm1, ymm6
.globl a_sub7
a_sub7:      vsubps ymm1, ymm1, ymm7
.globl a_mulr10
a_mulr10:    vmulps ymm1, ymm1, ymmword ptr [r10]
.globl a_acc
a_acc:       vaddps ymm0, ymm0, ymm1
.globl a_addr9
a_addr9:     add r9, 8

// ---- Q4_K f32 factor prologue ----
.globl p_movd
p_movd:      vmovd xmm2, dword ptr [r9-16]
.globl p_ph2ps
p_ph2ps:     vcvtph2ps xmm2, xmm2
.globl p_perm_d
p_perm_d:    vpermilps xmm8, xmm2, 0x00
.globl p_perm_m
p_perm_m:    vpermilps xmm9, xmm2, 0x55
.globl p_cvt4
p_cvt4:      vcvtdq2ps xmm12, xmm7
.globl p_mul4
p_mul4:      vmulps xmm12, xmm12, xmm8
.globl p_dup12
p_dup12:     vinsertf128 ymm12, ymm12, xmm12, 1
.globl p_dup13
p_dup13:     vinsertf128 ymm13, ymm13, xmm13, 1
.globl p_dup14
p_dup14:     vinsertf128 ymm14, ymm14, xmm14, 1
.globl p_dup15
p_dup15:     vinsertf128 ymm15, ymm15, xmm15, 1
.globl p_bc12_00
p_bc12_00:   vpermilps ymm6, ymm12, 0x00
.globl p_bc12_55
p_bc12_55:   vpermilps ymm6, ymm12, 0x55
.globl p_bc12_aa
p_bc12_aa:   vpermilps ymm6, ymm12, 0xaa
.globl p_bc12_ff
p_bc12_ff:   vpermilps ymm6, ymm12, 0xff
.globl p_bc13_00
p_bc13_00:   vpermilps ymm6, ymm13, 0x00
.globl p_bc13_55
p_bc13_55:   vpermilps ymm6, ymm13, 0x55
.globl p_bc13_aa
p_bc13_aa:   vpermilps ymm6, ymm13, 0xaa
.globl p_bc13_ff
p_bc13_ff:   vpermilps ymm6, ymm13, 0xff
.globl p_bd14_00
p_bd14_00:   vpermilps ymm7, ymm14, 0x00
.globl p_bd14_55
p_bd14_55:   vpermilps ymm7, ymm14, 0x55
.globl p_bd14_aa
p_bd14_aa:   vpermilps ymm7, ymm14, 0xaa
.globl p_bd14_ff
p_bd14_ff:   vpermilps ymm7, ymm14, 0xff
.globl p_bd15_00
p_bd15_00:   vpermilps ymm7, ymm15, 0x00
.globl p_bd15_55
p_bd15_55:   vpermilps ymm7, ymm15, 0x55
.globl p_bd15_aa
p_bd15_aa:   vpermilps ymm7, ymm15, 0xaa
.globl p_bd15_ff
p_bd15_ff:   vpermilps ymm7, ymm15, 0xff

// ---- Q4_K f32 FMA fold ----
.globl a_fnma213
a_fnma213:   vfnmadd213ps ymm1, ymm6, ymm7
.globl a_fnma231
a_fnma231:   vfnmadd231ps ymm0, ymm1, ymmword ptr [r10]

// ---- Q6_K f32 ----
.globl b_ldql
b_ldql:      vpmovzxbd ymm6, qword ptr [r9]
.globl b_ldqh
b_ldqh:      vpmovzxbd ymm7, qword ptr [r9+128]
.globl b_shr4
b_shr4:      vpsrld ymm6, ymm6, 4
.globl b_and4
b_and4:      vpand ymm6, ymm6, ymm4
.globl b_shr2
b_shr2:      vpsrld ymm7, ymm7, 2
.globl b_shr4b
b_shr4b:     vpsrld ymm7, ymm7, 4
.globl b_shr6
b_shr6:      vpsrld ymm7, ymm7, 6
.globl b_and5
b_and5:      vpand ymm7, ymm7, ymm5
.globl b_shl4
b_shl4:      vpslld ymm7, ymm7, 4
.globl b_or
b_or:        vpor ymm6, ymm6, ymm7
.globl b_add3
b_add3:      vpaddd ymm6, ymm6, ymm3
.globl b_cvt
b_cvt:       vcvtdq2ps ymm6, ymm6
.globl b_mul2
b_mul2:      vmulps ymm6, ymm6, ymm2
.globl b_mul1
b_mul1:      vmulps ymm6, ymm6, ymm1
.globl b_mulr10
b_mulr10:    vmulps ymm6, ymm6, ymmword ptr [r10]
.globl b_acc
b_acc:       vaddps ymm0, ymm0, ymm6
.globl b_fma
b_fma:       vfmadd231ps ymm0, ymm6, ymmword ptr [r10]
.globl b_lod
b_lod:       movzx eax, word ptr [r9+208]
.globl b_movdc
b_movdc:     vmovd xmm1, eax
.globl b_ph2ps
b_ph2ps:     vcvtph2ps xmm1, xmm1
.globl b_bcd
b_bcd:       vbroadcastss ymm1, xmm1
.globl b_sc_ld
b_sc_ld:     vpbroadcastb xmm2, byte ptr [r9+192]
.globl b_sc_sext
b_sc_sext:   vpmovsxbd xmm2, xmm2
.globl b_sc_cvt
b_sc_cvt:    vcvtdq2ps xmm2, xmm2
.globl b_sc_bc
b_sc_bc:     vbroadcastss ymm2, xmm2
.globl b_consts
b_consts:    vpcmpeqd ymm3, ymm3, ymm3
             vpslld ymm3, ymm3, 5
             vpcmpeqd ymm4, ymm4, ymm4
             vpsrld ymm4, ymm4, 28
             vpcmpeqd ymm5, ymm5, ymm5
             vpsrld ymm5, ymm5, 30
